function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is an integer between -1000 and 1000.';
  for (let i = 1; i < nums.length; i++) if (nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  return null;
}

