  const count = new Map();
  const tails = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) || 0) + 1);
  }
  for (const num of nums) {
    if (count.get(num) === 0) {
      continue;
    }
    count.set(num, count.get(num) - 1);
    if ((tails.get(num - 1) || 0) > 0) {
      tails.set(num - 1, tails.get(num - 1) - 1);
      tails.set(num, (tails.get(num) || 0) + 1);
    } else if ((count.get(num + 1) || 0) > 0 && (count.get(num + 2) || 0) > 0) {
      count.set(num + 1, count.get(num + 1) - 1);
      count.set(num + 2, count.get(num + 2) - 1);
      tails.set(num + 2, (tails.get(num + 2) || 0) + 1);
    } else {
      return false;
    }
  }
  return true;
}

