function isPossible(nums) {
  // Try every way to place each value: extend some open run ending at value - 1, or open a new run.
  const runs = [];
  const place = (index) => {
    if (index === nums.length) return runs.every(r => r.length >= 3);
    const value = nums[index];
    const tried = new Set();
    for (const run of runs) {
      if (run.last !== value - 1 || tried.has(run.length)) continue;
      tried.add(run.length);
      run.last = value; run.length++;
      const ok = place(index + 1);
      run.last = value - 1; run.length--;
      if (ok) return true;
    }
    runs.push({ last: value, length: 1 });
    const ok = place(index + 1);
    runs.pop();
    return ok;
  };
  return place(0);
}

