function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small' && rand() < 0.35) {
    const n = int(1, 10);
    return [Array.from({ length: n }, () => int(-3, 4)).sort((a, b) => a - b)];
  }
  // Build a valid split from random runs, then sometimes break it by adding or removing one value.
  const limit = size === 'large' ? 2000 : 12;
  const low = size === 'large' ? -1000 : -4;
  const high = size === 'large' ? 1000 : 6;
  const nums = [];
  while (true) {
    const length = int(3, size === 'large' ? 40 : 5);
    if (nums.length + length > limit) break;
    const start = int(low, high - length + 1);
    for (let k = 0; k < length; k++) nums.push(start + k);
    if (size === 'small' && rand() < 0.3) break;
  }
  const twist = rand();
  if (twist < 0.25 && nums.length > 1) nums.splice(int(0, nums.length - 1), 1);
  else if (twist < 0.5 && nums.length < limit) nums.push(int(low, high));
  if (nums.length === 0) nums.push(int(low, high));
  return [nums.sort((a, b) => a - b)];
}
